#!/bin/bash
# Sync the prompt and lessons into the build context,
# then build the image. Rerun after changing the prompt or lessons.
set -euo pipefail
source "$(dirname "$0")/common.sh"
cd "$here"
for f in "$data"/*_PROMPT.md; do [ -e "$f" ] && cp "$f" agent/prompts/; done
rm -f agent/lessons/*.md
for f in "$data"/LESSONS*.md "$data"/*_learnings.md; do
  [ -e "$f" ] && cp "$f" agent/lessons/
done
# skills/ is generated by host/build-skills.sh; verify it was not edited
# by hand since.
[ -e skills/MANIFEST.sha256 ] || "$here/host/build-skills.sh"
(cd skills && sha256sum --quiet -c MANIFEST.sha256) || {
  echo "skills/ does not match skills/MANIFEST.sha256; rerun host/build-skills.sh" >&2; exit 1; }
podman build ${NOCACHE:+--no-cache} \
  --build-arg INTERNAL_CA_REPO="${INTERNAL_CA_REPO:-}" \
  --build-arg INTERNAL_CA_PACKAGE="${INTERNAL_CA_PACKAGE:-}" \
  -t localhost/test-enabler:latest .
echo "built localhost/test-enabler:latest with lessons: $(ls agent/lessons | tr '\n' ' ')"
